/**
 * @summary Get all currently live deals for the discovery feed
 */
export const getGetLiveFeedUrl = (params?: GetLiveFeedParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/feed/live?${stringifiedParams}`
    : `/api/feed/live`;
};

export const getLiveFeed = async (
  params?: GetLiveFeedParams,
  options?: RequestInit,
): Promise<DealWithVenue[]> => {
  return customFetch<DealWithVenue[]>(getGetLiveFeedUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetLiveFeedQueryKey = (params?: GetLiveFeedParams) => {
  return [`/api/feed/live`, ...(params ? [params] : [])] as const;
};

